import json, re, glob, os, csv, sys
root = sys.argv[1]; os.chdir(root)
games = {}  # sid -> dict
def add(sid, case, score, src, t=None, deal=None):
    if not sid or not re.fullmatch(r'[0-9a-f]{16}', sid): return
    case = case.replace('case:', '') if case else case
    g = games.setdefault(sid, dict(sid=sid, case=case, score=score, deal=deal, srcs=[], t=t))
    if g['score'] is None and score is not None: g['score'] = score
    if not g['case'] and case: g['case'] = case
    if g['t'] is None and t: g['t'] = t
    if src not in g['srcs']: g['srcs'].append(src)
for l in open('knowledge/experiments.jsonl'):
    r = json.loads(l)
    add(r.get('session_id'), r['case_id'], r.get('score'), f"lab/{r['batch']} [{r['variant']}]", r.get('t'), r.get('deal'))
for f in glob.glob('runs/*/results.json'):
    run = f.split('/')[1]; t = None
    try: t = json.load(open(f.replace('results.json', 'metadata.json'))).get('started')
    except Exception: pass
    for case, v in json.load(open(f)).items():
        res = v.get('result') or {}
        add(v.get('session_id'), case, res.get('score'), run, t, res.get('deal'))
for f in glob.glob('runs/*/P*.txt'):
    txt = open(f).read(); run = f.split('/')[1]; case = os.path.basename(f)[:-4]
    sid = re.search(r'session ([0-9a-f]{16})', txt) or re.search(r'replay/([0-9a-f]{16})', txt)
    sc = re.findall(r'"score": ([0-9.\-e]+)', txt)
    if sid: add(sid.group(1), case, float(sc[-1]) if sc else None, run)
for f in glob.glob('runs/best_replays/*.md'):
    m = re.match(r'# (\S+) - score ([0-9.]+) - replay \S+/replay/([0-9a-f]+)', open(f).readline())
    if m: add(m.group(3), m.group(1), float(m.group(2)), 'best_replays')
rows = sorted(games.values(), key=lambda g: (g['case'], -(g['score'] if g['score'] is not None else -9)))
with open(sys.argv[2], 'w', newline='') as fh:
    w = csv.writer(fh); w.writerow(['case', 'score', 'deal', 'replay_url', 'session_id', 'sources'])
    for g in rows:
        w.writerow([g['case'], '' if g['score'] is None else round(g['score'], 3), g['deal'], f"https://arena.tacto.ai/replay/{g['sid']}", g['sid'], '; '.join(g['srcs'])])
print(len(rows), 'games')
from collections import defaultdict
by = defaultdict(list)
for g in rows: by[g['case']].append(g)
for c, gs in sorted(by.items()):
    s = [g['score'] for g in gs if g['score'] is not None]
    print(c, len(gs), 'best', max(s) if s else None, gs[0]['sid'])
